190	      var ctx = canvas.getContext("2d")
191	      if (!ctx) { return }
192	      var cx = size / 2
193	      var cy = size / 2
194	      ctx.clearRect(0, 0, size, size)
195	
196	      // 外圈细环 - 医疗风格柔和色调
197	      ctx.beginPath()
198	      ctx.lineWidth = 1.5
199	      ctx.strokeStyle = "rgba(0, 201, 167, 0.15)"
