226	      ctx.lineWidth = 6
227	      ctx.strokeStyle = "rgba(0, 201, 167, 0.1)"
228	      ctx.lineCap = "round"
229	      ctx.moveTo(cx + secR1 * Math.cos(secAng), cy + secR1 * Math.sin(secAng))
230	      ctx.lineTo(cx + secR2 * Math.cos(secAng), cy + secR2 * Math.sin(secAng))
231	      ctx.stroke()
232	
233	      // 中层发光
234	      ctx.beginPath()
235	      ctx.lineWidth = 3
236	      ctx.strokeStyle = "rgba(0, 201, 167, 0.35)"
237	      ctx.moveTo(cx + secR1 * Math.cos(secAng), cy + secR1 * Math.sin(secAng))
238	      ctx.lineTo(cx + secR2 * Math.cos(secAng), cy + secR2 * Math.sin(secAng))
239	      ctx.stroke()
240	
241	      // 内层实体
242	      ctx.beginPath()
243	      ctx.lineWidth = 1.5
244	      ctx.strokeStyle = "rgba(0, 201, 167, 0.8)"
245	      ctx.lineCap = "round"
246	      ctx.moveTo(cx + secR1 * Math.cos(secAng), cy + secR1 * Math.sin(secAng))
247	      ctx.lineTo(cx + secR2 * Math.cos(secAng), cy + secR2 * Math.sin(secAng))
248	      ctx.stroke()
249	
