251	      ctx.beginPath()
252	      ctx.arc(cx + secR2 * Math.cos(secAng), cy + secR2 * Math.sin(secAng), 5, 0, Math.PI * 2)
253	      ctx.fillStyle = "rgba(0, 201, 167, 0.15)"
254	      ctx.fill()
255	      ctx.beginPath()
256	      ctx.arc(cx + secR2 * Math.cos(secAng), cy + secR2 * Math.sin(secAng), 2, 0, Math.PI * 2)
