282	      ctx.lineWidth = outerR - innerR
283	      ctx.strokeStyle = "rgba(0, 201, 167," + (opacity * 0.4).toFixed(3) + ")"
284	      ctx.stroke()
285	
286	      // 外圈呼吸光环
287	      var innerR2 = size / 2 - 52
288	      var outerR2 = size / 2 - 44
289	      ctx.beginPath()
290	      ctx.arc(cx, cy, (innerR2 + outerR2) / 2, 0, Math.PI * 2)
291	      ctx.lineWidth = outerR2 - innerR2
292	      ctx.strokeStyle = "rgba(0, 201, 167," + (opacity * 0.15).toFixed(3) + ")"
293	      ctx.stroke()
294	    } catch (e) { /* skip */ }
295	  },
