297	  drawPulseWave() {
298	    var page = this
299	    var size = getScreenShape().screenWidth
300	    if (!size) { return }
301	    try {
302	      var canvas = page.$element("pulseCanvas")
303	      if (!canvas) { return }
304	      var ctx = canvas.getContext("2d")
305	      if (!ctx) { return }
306	
307	      var width = size
308	      var height = 60
309	      var cy = height / 2
310	      var opacity = parseFloat(page.hintOpacity) || 0.5
311	
312	      ctx.clearRect(0, 0, width, height)
313	
314	      // 绘制脉搏波形
315	      ctx.beginPath()
316	      ctx.strokeStyle = "rgba(74, 144, 217," + (opacity * 0.6).toFixed(3) + ")"
317	      ctx.lineWidth = 2
318	      ctx.lineCap = "round"
319	      ctx.lineJoin = "round"
320	
321	      var time = Date.now() / 1000
322	      var frequency = 1.2
323	
324	      for (var x = 0; x < width; x++) {
325	        var t = (x / width) * Math.PI * 4 + time * frequency
326	        // ECG 风格波形
327	        var y = cy
328	        var phase = t % (Math.PI * 2)
329	        if (phase > 2.5 && phase < 3.0) {
330	          // QRS 波群
331	          y = cy - Math.sin((phase - 2.5) * Math.PI * 4) * 20
332	        } else if (phase > 3.0 && phase < 3.3) {
333	          // T 波
334	          y = cy - Math.sin((phase - 3.0) * Math.PI * 3.33) * 8
335	        } else {
336	          // 基线
337	          y = cy + Math.sin(t * 0.5) * 2
338	        }
339	
340	        if (x === 0) {
341	          ctx.moveTo(x, y)
342	        } else {
343	          ctx.lineTo(x, y)
344	        }
345	      }
346	      ctx.stroke()
347	    } catch (e) { /* skip */ }
348	  },
