1	/**
2	 * watch-face.js - 表盘形状检测、安全区计算与字体缩放
3	 *
4	 * 圆形表盘使用内接正方形作为内容安全区，保证四角不被圆弧裁切。
5	 * 目标设备 466×466 物理像素，Vela 运行时 CSS 1px = 1 物理 px（无 density 缩放），
6	 * 故布局坐标系就是 466×466。@system.device.getInfo() 返回的 screenWidth/Height
7	 * 即为物理像素，直接使用即可。
8	 */
9	
10	import device from "@system.device"
11	
12	var screenW = 0
13	var screenH = 0
14	var shapeCache = null
15	
16	// 目标设备表盘参数：466×466 物理像素、density 320、正圆。
17	// Vela 快应用运行时对 device-width 不做 density 换算，CSS 1px = 1 物理 px。
18	var DEVICE_PROFILE = {
19	  screenWidth: 466,
20	  screenHeight: 466,
21	  shape: "circle"
22	}
23	
24	// getInfo() 成功返回的设备信息（覆盖 profile）
25	var deviceInfo = null
26	var refreshDone = false
27	var refreshCbs = []
28	
29	function detectShape() {
30	  var width = DEVICE_PROFILE.screenWidth
31	  var height = DEVICE_PROFILE.screenHeight
32	  var explicitShape = DEVICE_PROFILE.shape
33	
34	  if (deviceInfo) {
35	    // screenWidth/Height 即物理像素，直接使用。
36	    width = deviceInfo.screenWidth || width
37	    height = deviceInfo.screenHeight || height
38	    if (deviceInfo.screenShape) { explicitShape = deviceInfo.screenShape }
39	    else if (deviceInfo.shape) { explicitShape = deviceInfo.shape }
40	  }
41	
42	  screenW = width
43	  screenH = height
44	
45	  var isRound = false
46	  if (explicitShape === "circle" || explicitShape === "round") {
47	    isRound = true
48	  } else if (explicitShape === "rect" || explicitShape === "square" || explicitShape === "pill-shaped") {
49	    isRound = false
50	  } else {
51	    var ratio = screenW / screenH
52	    isRound = ratio > 0.9 && ratio < 1.1
53	  }
54	
55	  shapeCache = {
56	    isRound: isRound,
57	    isSquare: !isRound,
58	    screenWidth: screenW,
59	    screenHeight: screenH
60	  }
61	  return shapeCache
62	}
63	
64	// ─── 形状检测 ──────────────────────────────────────────
65	
66	export function getScreenShape() {
67	  if (!shapeCache) { detectShape() }
68	  return shapeCache
69	}
70	
71	export function getScreenHeight() {
72	  return getScreenShape().screenHeight
73	}
74	
75	// 异步拉取真实设备信息，覆盖兜底后回调（供页面 re-compute 样式）。
76	export function refreshScreenShape(cb) {
77	  if (cb) { refreshCbs.push(cb) }
78	  if (refreshDone) { return }
79	  refreshDone = true
80	
81	  function fire() {
82	    for (var i = 0; i < refreshCbs.length; i++) { refreshCbs[i](getScreenShape()) }
83	    refreshCbs = []
84	  }
85	
86	  try {
87	    device.getInfo({
88	      success: function(info) {
89	        deviceInfo = info || null
90	        try { console.log("[VelaGuard] getInfo=" + JSON.stringify(info)) } catch (e) { /* skip */ }
91	        shapeCache = null
92	        detectShape()
93	        fire()
94	      },
95	      fail: function() { fire() }
96	    })
97	  } catch (e) { fire() }
98	}
99	
100	// ─── 安全区内边距 ────────────────────────────────────
101	
102	export function getSafePadding() {
103	  var shape = getScreenShape()
104	  if (shape.isRound) {
105	    // 使用 0.72 内接正方形，四周留白 ≈ 0.14D（约 65px @466），
106	    // 在保证圆弧不裁切的前提下最大化内容区域。
107	    // 原 0.62 系数浪费太多空间，0.72 是圆形手表 UI 的甜点值。
108	    var diameter = Math.min(shape.screenWidth, shape.screenHeight)
109	    var pad = Math.round(((1 - 0.72) / 2) * diameter)
110	    return { top: pad, right: pad, bottom: pad, left: pad }
111	  }
112	  return { top: 18, right: 18, bottom: 16, left: 18 }
113	}
114	
115	// ─── 内容列最大宽度（圆形=内接正方形边长，方形=全宽减内边距） ──
116	
117	export function getContentWidth() {
118	  var shape = getScreenShape()
119	  if (shape.isRound) {
120	    // 与 getSafePadding 的 0.72 系数对齐，确保内容列宽度在安全区内
121	    return Math.round(Math.min(shape.screenWidth, shape.screenHeight) * 0.72)
122	  }
123	  return shape.screenWidth - 36
124	}
125	
126	// ─── 内容 padding（圆形安全区） ───────────────────────
127	
128	export function getContentPadding() {
129	  var p = getSafePadding()
130	  return p.top + "px " + p.right + "px " + p.bottom + "px " + p.left + "px"
131	}
132	
133	// ─── 圆角 ────────────────────────────────────────────
134	
135	export function getCardRadius() {
136	  return getScreenShape().isRound ? 26 : 20
137	}
138	
139	export function getButtonRadius() {
140	  return getScreenShape().isRound ? 24 : 23
141	}
142	
143	// ─── 字体缩放 ──────────────────────────────────────────
144	
145	export function getFontScale() {
146	  return getScreenShape().isRound ? 1.15 : 1.0
147	}
148	
149	export function fs(baseSize) {
150	  var scale = getFontScale()
151	  return Math.round(baseSize * scale)
152	}
153	
154	// ─── 按钮高度缩放 ──────────────────────────────────────
155	
156	export function getButtonHeight(base) {
157	  return getScreenShape().isRound ? Math.round(base * 1.15) : base
158	}
159	
160	// ─── 卡片是否使用竖向布局 ────────────────────────────
161	
162	export function useVerticalLayout() {
163	  return getScreenShape().isRound
164	}
165	
166	// ─── 动态 padding 字符串 ──────────────────────────────
167	
168	export function padStr() {
169	  var p = getSafePadding()
170	  return p.top + "px " + p.right + "px " + p.bottom + "px " + p.left + "px"
171	}
172	
173	// ─── 中心表盘尺寸 ─────────────────────────────────────
174	
175	/**
176	 * 计算中心表盘的最佳尺寸
177	 * @param {number} contentWidth - 内容区宽度
178	 * @returns {number} 表盘直径
179	 */
180	export function getDialSize(contentWidth) {
181	  return Math.round(contentWidth * 0.48)
182	}
183	
184	/**
185	 * 计算 SOS 按钮的最佳尺寸
186	 * @param {number} contentWidth - 内容区宽度
187	 * @returns {number} 按钮直径
188	 */
189	export function getSosSize(contentWidth) {
190	  return Math.max(52, Math.round(contentWidth * 0.18))
191	}
192	
193	/**
194	 * 底部导航栏高度
195	 * @returns {number}
196	 */
197	export function getTabBarHeight() {
198	  return getScreenShape().isRound ? 56 : 52
199	}
