94	<script>
95	import router from "@system.router"
96	import { createWindow, pushSample, resetWindow, assessWindow } from "../../common/fall-model.js"
97	import { createFallDetector } from "../../common/fall-detector.js"
98	import { createReplayEngine, getScenarioCatalog } from "../../common/sensor-replay.js"
99	import { createAlert } from "../../common/event-machine.js"
100	import { loadSettings } from "../../common/storage.js"
101	import { getScreenShape, padStr, fs, getCardRadius, getScreenHeight, getSafePadding, refreshScreenShape } from "../../common/watch-face.js"
102	import { vibrateLight } from "../../common/touch-feedback.js"
103	import { createPageTransition } from "../../common/anim-utils.js"
104	import { colors } from "../../common/theme.js"
105	
106	function magnitude(x, y, z) { return Math.sqrt(x * x + y * y + z * z) }
107	
108	export default {
109	  private: {
110	    sourceText: "模拟", statusClass: "status-ready", statusKicker: "准备就绪",
111	    statusTitle: "选择一个场景", statusDescription: "验证端侧识别与误报抑制",
112	    statusDotClass: "dot-ready",
113	    currentG: "--", peakG: "--", riskScore: "--",
114	    isRunning: false, progressWidth: "0%", scenarios: getScenarioCatalog(),
115	    sensorStatus: false, heartRate: "--",
116	    stage1Class: "stage-off", stage2Class: "stage-off", stage3Class: "stage-off",
117	    stage1NumClass: "num-off", stage2NumClass: "num-off", stage3NumClass: "num-off",
118	    stage1LineClass: "line-off", stage2LineClass: "line-off",
119	    stageNote: "等待冲击峰值触发候选",
120	    contentPad: "", headerPad: "", fs9: 9, fs10: 10, fs11: 11, fs12: 12, fs15: 15, fs17: 17, fs18: 18, fs22: 22, fs24: 24, fs28: 28,
121	    cr: 20, sr: 14, backW: 42, backR: 21, cardPad: 14, scPad: 12, scrollH: 0,
122	    enterStyle: ""
123	  },
124	
125	  onInit() {
126	    var page = this
127	    this.scrollH = getScreenHeight()
128	    this.sampleWindow = createWindow(64)
129	    this.enterTransition = createPageTransition({ duration: 250, translateY: 12 })
130	    this.computeStyles()
131	    refreshScreenShape(function() { page.computeStyles() })
132	
133	    this.replayDetector = createFallDetector({
134	      stillMs: 1500,
135	      immobilityMs: 4000,
136	      onState: function(type, detail) { page.onDetectorState(type, detail) }
137	    })
138	
139	    this.replay = createReplayEngine({
140	      onStart: function(d) { page.onReplayStart(d) },
141	      onSample: function(s, i, t) { page.onReplaySample(s, i, t) },
142	      onComplete: function(d) { page.onReplayComplete(d) }
143	    })
144	  },
145	
146	  computeStyles() {
147	    var r = getScreenShape().isRound
148	    var safe = getSafePadding()
149	    var edge = r ? Math.round(safe.left * 0.50) : 14
150	    this.headerPad = "0 " + edge + "px"
151	    this.contentPad = padStr()
152	    this.fs9 = fs(9); this.fs10 = fs(10); this.fs11 = fs(11); this.fs12 = fs(12); this.fs15 = fs(15)
153	    this.fs17 = fs(17); this.fs18 = fs(18); this.fs22 = fs(22); this.fs24 = fs(24); this.fs28 = fs(28)
154	    this.cr = getCardRadius(); this.sr = r ? 16 : 12
155	    this.backW = r ? 46 : 42; this.backR = Math.floor(this.backW / 2)
156	    this.cardPad = r ? 14 : 12; this.scPad = r ? 12 : 10
157	  },
158	
159	  onShow() {
160	    var page = this
161	    loadSettings(function(s) { page.sourceText = s.useRealSensor ? "真机" : "模拟" })
162	    this.enterTransition.trigger()
163	    this._enterTimer = setInterval(function() { page.enterStyle = page.enterTransition.getStyle() }, 16)
164	  },
165	
166	  onDestroy() { if (this.replay) { this.replay.stop() }; if (this._enterTimer) { clearInterval(this._enterTimer); this._enterTimer = null } },
167	
168	  runScenario(id) {
169	    if (!this.isRunning) {
170	      vibrateLight()
171	      this.replay.start(id)
172	    }
173	  },
174	
175	  setStage(a, b, c) {
176	    this.stage1Class = a === "on" ? "stage-on" : a === "done" ? "stage-done" : "stage-off"
177	    this.stage2Class = b === "on" ? "stage-on" : b === "done" ? "stage-done" : "stage-off"
178	    this.stage3Class = c === "on" ? "stage-on" : c === "done" ? "stage-done" : "stage-off"
179	    this.stage1NumClass = a === "on" ? "num-on" : a === "done" ? "num-done" : "num-off"
180	    this.stage2NumClass = b === "on" ? "num-on" : b === "done" ? "num-done" : "num-off"
181	    this.stage3NumClass = c === "on" ? "num-on" : c === "done" ? "num-done" : "num-off"
182	    this.stage1LineClass = a === "done" ? "line-active" : "line-off"
183	    this.stage2LineClass = b === "done" ? "line-active" : "line-off"
184	  },
185	
186	  onDetectorState(type, detail) {
187	    if (type === "candidate") {
188	      this.setStage("on", "off", "off")
189	      this.statusDotClass = "dot-warning"
190	      this.stageNote = "捕获冲击峰值 " + detail.peakG.toFixed(1) + "g → 进入静止复核"
191	    } else if (type === "cancelled") {
192	      this.setStage("off", "off", "off")
193	      this.statusDotClass = "dot-safe"
194	      this.stageNote = "恢复运动，候选取消（误报抑制）"
195	    } else if (type === "fall") {
196	      this.setStage("done", "done", "on")
197	      this.statusDotClass = "dot-danger"
198	      this.stageNote = "静止确认通过 · 判定疑似跌倒"
199	    } else if (type === "immobility") {
200	      this.setStage("off", "done", "on")
201	      this.statusDotClass = "dot-warning"
202	      this.stageNote = "持续低活动 · 判定异常静止"
203	    }
204	  },
205	
206	  onReplayStart(def) {
207	    resetWindow(this.sampleWindow)
208	    this.replayDetector.reset()
209	    this.setStage("off", "off", "off")
210	    this.stageNote = "等待冲击峰值触发候选"
211	    this.isRunning = true; this.progressWidth = "0%"; this.statusClass = "status-running"
212	    this.statusDotClass = "dot-running"
213	    this.statusKicker = "正在分析"; this.statusTitle = def.title
214	    this.statusDescription = "提取多传感器运动特征"
215	    this.currentG = "--"; this.peakG = "0.00"; this.riskScore = "--"
216	    this.sensorStatus = true; this.heartRate = "--"
217	  },
218	
219	  onReplaySample(sample, index, total) {
220	    pushSample(this.sampleWindow, sample)
221	    this.replayDetector.push(sample)
222	    var g = magnitude(sample.x, sample.y, sample.z)
223	    this.currentG = g.toFixed(2)
224	    this.peakG = Math.max(Number(this.peakG), g).toFixed(2)
225	    this.progressWidth = Math.round((index / total) * 100) + "%"
226	    if (sample.heartRate) { this.heartRate = sample.heartRate + "bpm" }
227	  },
228	
229	  onReplayComplete(def) {
230	    var page = this
231	    var result = assessWindow(this.sampleWindow)
232	    this.isRunning = false; this.progressWidth = "100%"
233	    this.riskScore = Math.round(result.confidence * 100) + "%"
234	    if (result.label === "normal") {
235	      this.statusClass = "status-safe"; this.statusKicker = "未发现风险"
236	      this.statusDotClass = "dot-safe"
237	      this.statusTitle = "状态正常"
238	      this.statusDescription = def.id === "shake" ? "冲击后仍持续运动" : "运动符合日常活动模式"
239	      this.setStage("off", "off", "off")
240	      this.stageNote = def.id === "shake" ? "恢复运动，候选取消（误报抑制）" : "未触发风险判定"
241	      vibrateLight()
242	      return
243	    }
244	    this.statusClass = "status-warning"; this.statusKicker = "发现风险"
245	    this.statusDotClass = "dot-danger"
246	    this.statusTitle = result.label === "fall" ? "疑似跌倒" : "异常静止"
247	    this.statusDescription = "即将进入安全确认"
248	    this.setStage("done", "done", "on")
249	    this.stageNote = result.label === "fall" ? "静止确认通过 · 判定疑似跌倒" : "持续低活动 · 判定异常静止"
250	    vibrateLight()
251	    setTimeout(function() {
252	      page.$app.$def.setCurrentAlert(createAlert(result, def.title + "回放"))
253	      router.push({ uri: "/pages/alert" })
254	    }, 1500)
255	  },
256	
257	  goBack() { router.back() }
258	}
259	</script>
