24	/**
25	 * 生成按钮的按压态样式字符串
26	 * @param {string} normalBg - 正常背景色
27	 * @param {string} pressedBg - 按压背景色（可选，默认变暗15%）
28	 * @returns {object} { normalStyle, pressedStyle, onTouchStart, onTouchEnd }
29	 */
30	export function createButtonFeedback(normalBg, pressedBg) {
31	  var pressed = false
32	
33	  function onTouchStart() {
34	    pressed = true
35	    vibrateLight()
36	  }
37	
38	  function onTouchEnd() {
39	    pressed = false
40	  }
41	
42	  function isPressed() {
43	    return pressed
44	  }
45	
46	  return {
47	    onTouchStart: onTouchStart,
48	    onTouchEnd: onTouchEnd,
49	    isPressed: isPressed
