68	 * 用于管理按钮/卡片的按压状态和视觉反馈
69	 */
70	export function createInteractionState() {
71	  var state = {
72	    pressedId: null,
73	    pressedAt: 0
74	  }
75	
76	  function press(id) {
77	    state.pressedId = id
78	    state.pressedAt = Date.now()
79	    vibrateLight()
80	  }
81	
82	  function release() {
83	    state.pressedId = null
84	  }
85	
86	  function isPressed(id) {
87	    return state.pressedId === id
88	  }
89	
90	  function getPressedStyle(id, normalStyle) {
91	    if (state.pressedId === id) {
92	      return (normalStyle || "") + " opacity: 0.8; transform: scale(0.97);"
93	    }
94	    return normalStyle || ""
95	  }
96	
97	  return {
98	    press: press,
99	    release: release,
