178	export function flushQueuedEvents(callback) {
179	  loadEvents(function(events) {
180	    let changed = 0
181	    for (let index = 0; index < events.length; index += 1) {
182	      if (events[index].status === "queued") {
183	        events[index].status = "sent"
184	        events[index].statusLabel = "已补发"
185	        events[index].sentAt = Date.now()
186	        if (events[index].message) {
187	          events[index].message.deviceStatus = "电量68%，网络恢复后已补发"
188	        }
189	        appendTimeline(events[index], "离线求助已补发", "网络恢复，消息发送状态更新为已补发")
190	        changed += 1
191	      } else if (events[index].status === "withdrawal_queued") {
192	        events[index].status = "withdrawn"
193	        events[index].statusLabel = "撤回已补发"
194	        events[index].withdrawalSentAt = Date.now()
195	        appendTimeline(
196	          events[index],
197	          "撤回更新已补发",
198	          "联系人已收到“用户已确认安全”状态更新"
199	        )
200	        changed += 1
201	      }
202	    }
203	
204	    saveEvents(events, function() {
205	      if (callback) {
206	        callback(changed, events)
207	      }
208	    })
209	  })
210	}
