/**
 * theme.js - 双主题设计系统（渐变活力风）
 *
 * 深色主题：深空蓝底 + 青绿强调 + 玻璃态卡片
 * 浅色主题：柔白底 + 沉稳青绿 + 清爽卡片
 *
 * 所有页面通过 getActiveTheme() 获取当前主题颜色，
 * Canvas 绘制通过 getThemeColors() 获取。
 */

// ─── 深色主题（默认）──────────────────────────────────────

