export function getHeartRateColor(hr) {
  if (hr <= 100) return themeData.safe
  if (hr <= 140) return themeData.warning
  return themeData.danger
}

export function getHeartRateZone(hr) {
  if (hr < 60) return { label: '静息', color: themeData.info }
  if (hr < 100) return { label: '正常', color: themeData.safe }
  if (hr < 140) return { label: '偏高', color: themeData.warning }
  return { label: '危险', color: themeData.danger }
}

/**
 * 生成 CSS 渐变字符串
 */
export function linearGradient(colorArr, angle) {
  angle = angle || 135
  return 'linear-gradient(' + angle + 'deg, ' + colorArr.join(', ') + ')'
}

/**
 * 生成径向渐变字符串
 */
export function radialGradient(colorArr) {
