}

/**
 * 卡片样式（玻璃态）
 */
export function getCardStyle(opts) {
  opts = opts || {}
  var t = themeData
  var parts = [
    'background-color: ' + (opts.transparent ? t.surfaceGlass : t.surface),
    'border-radius: ' + (opts.radius || radius.lg) + 'px',
    'box-shadow: ' + t.cardShadow,
