// ─── 数字平滑过渡 ──────────────────────────────────────

/**
 * 创建数字平滑过渡器 — 心率、步数等数值平滑变化
 * @param {number} initial - 初始值
 * @returns {object} { set, getValue, getDisplay }
 */
export function createSmoothNumber(initial) {
  var current = initial || 0
  var target = initial || 0
  var display = initial || 0
  var startTime = 0
  var duration = 300
  var fromVal = initial || 0
  var timer = null

  function set(newVal, dur) {
    if (newVal === target) return
    fromVal = display
    target = newVal
    startTime = Date.now()
    duration = dur || 300
    if (!timer) { _tick() }
  }

  function _tick() {
    var elapsed = Date.now() - startTime
    var t = Math.min(elapsed / duration, 1)
    var eased = easeOutCubic(t)
    display = Math.round(fromVal + (target - fromVal) * eased)
    if (t < 1) {
      timer = setTimeout(_tick, 16)
    } else {
      timer = null
      display = target
    }
  }

  function getValue() { return target }
  function getDisplay() { return display }

  function stop() {
    if (timer) { clearTimeout(timer); timer = null }
  }

  return { set: set, getValue: getValue, getDisplay: getDisplay, stop: stop }
}

// ─── Canvas 渐变进度弧 ────────────────────────────────

/**
 * 绘制渐变进度弧线（支持多色渐变 + 端点光晕）
 * @param {CanvasRenderingContext2D} ctx
 * @param {number} cx - 圆心 x
 * @param {number} cy - 圆心 y
 * @param {number} r - 半径
 * @param {number} lineWidth - 线宽
 * @param {number} pct - 进度 0~1
 * @param {string[]} colors - 渐变色数组
 * @param {object} [opts] - 可选配置
 */
export function drawGradientArc(ctx, cx, cy, r, lineWidth, pct, colors, opts) {
  opts = opts || {}
  var startAngle = opts.startAngle || (-Math.PI / 2)
  var glowSize = opts.glowSize || 6

  // 底环
  ctx.beginPath()
  ctx.lineWidth = lineWidth
  ctx.strokeStyle = opts.trackColor || 'rgba(255, 255, 255, 0.06)'
  ctx.arc(cx, cy, r, 0, Math.PI * 2)
  ctx.stroke()

  if (pct <= 0) return

  var endAngle = startAngle + Math.PI * 2 * Math.min(pct, 1)

  // 渐变弧
  var gradient = ctx.createLinearGradient(
    cx + r * Math.cos(startAngle), cy + r * Math.sin(startAngle),
    cx + r * Math.cos(endAngle), cy + r * Math.sin(endAngle)
  )
  for (var i = 0; i < colors.length; i++) {
    gradient.addColorStop(i / Math.max(colors.length - 1, 1), colors[i])
  }

  ctx.beginPath()
  ctx.lineWidth = lineWidth
  ctx.lineCap = 'round'
  ctx.strokeStyle = gradient
  ctx.arc(cx, cy, r, startAngle, endAngle)
  ctx.stroke()

  // 端点光晕
  if (opts.glow !== false && pct > 0.01) {
    var tipX = cx + r * Math.cos(endAngle)
    var tipY = cy + r * Math.sin(endAngle)
    ctx.beginPath()
    ctx.arc(tipX, tipY, glowSize, 0, Math.PI * 2)
    ctx.fillStyle = colors[colors.length - 1] + '40'
    ctx.fill()
    ctx.beginPath()
    ctx.arc(tipX, tipY, glowSize / 2, 0, Math.PI * 2)
    ctx.fillStyle = colors[colors.length - 1] + '90'
    ctx.fill()
  }
}

// ─── Canvas 发光效果 ────────────────────────────────────

/**
 * 在 Canvas 上绘制发光圆点
 * @param {CanvasRenderingContext2D} ctx
 * @param {number} x
 * @param {number} y
 * @param {number} r - 半径
 * @param {string} color - 颜色
 * @param {number} [glowR] - 光晕半径（默认 r*3）
 */
export function drawGlowDot(ctx, x, y, r, color, glowR) {
  glowR = glowR || r * 3
  // 外层光晕
  ctx.beginPath()
  ctx.arc(x, y, glowR, 0, Math.PI * 2)
  ctx.fillStyle = color + '15'
  ctx.fill()
  // 中层光晕
  ctx.beginPath()
  ctx.arc(x, y, glowR * 0.6, 0, Math.PI * 2)
  ctx.fillStyle = color + '30'
  ctx.fill()
  // 内层实体
  ctx.beginPath()
  ctx.arc(x, y, r, 0, Math.PI * 2)
  ctx.fillStyle = color
  ctx.fill()
}

// ─── 秒针光晕拖尾 ─────────────────────────────────────

/**
 * 绘制带光晕拖尾的秒针
 * @param {CanvasRenderingContext2D} ctx
 * @param {number} cx - 圆心 x
 * @param {number} cy - 圆心 y
 * @param {number} r1 - 内径
 * @param {number} r2 - 外径
 * @param {number} angle - 角度（弧度）
 * @param {string} color - 颜色
 */
export function drawGlowHand(ctx, cx, cy, r1, r2, angle, color) {
  var cos = Math.cos(angle)
  var sin = Math.sin(angle)

  // 光晕层（宽 + 透明）
  ctx.beginPath()
  ctx.lineWidth = 8
  ctx.strokeStyle = color + '18'
  ctx.lineCap = 'round'
  ctx.moveTo(cx + r1 * cos, cy + r1 * sin)
  ctx.lineTo(cx + r2 * cos, cy + r2 * sin)
  ctx.stroke()

  // 中间层
  ctx.beginPath()
  ctx.lineWidth = 4
  ctx.strokeStyle = color + '50'
  ctx.lineCap = 'round'
  ctx.moveTo(cx + r1 * cos, cy + r1 * sin)
  ctx.lineTo(cx + r2 * cos, cy + r2 * sin)
  ctx.stroke()

  // 实体层
  ctx.beginPath()
  ctx.lineWidth = 2
  ctx.strokeStyle = color
  ctx.lineCap = 'round'
  ctx.moveTo(cx + r1 * cos, cy + r1 * sin)
  ctx.lineTo(cx + r2 * cos, cy + r2 * sin)
  ctx.stroke()

  // 尾端光点
  drawGlowDot(ctx, cx + r2 * cos, cy + r2 * sin, 2, color, 6)
}

